begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
set local timezone='Pacific/Honolulu';
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)
select ('a9000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','agenda-'||n||'@example.invalid','x',now(),now(),now() from generate_series(1,6) n;
insert into public.staff_users(user_id,role) values('a9000000-0000-4000-8000-000000000001','admin'),('a9000000-0000-4000-8000-000000000002','office'),('a9000000-0000-4000-8000-000000000003','technician'),('a9000000-0000-4000-8000-000000000004','technician');
insert into public.customers(id,name) values('c9000000-0000-4000-8000-000000000001','Klient Alfa'),('c9000000-0000-4000-8000-000000000002','Klient Beta');
insert into public.staff_customer_assignments(user_id,customer_id) values('a9000000-0000-4000-8000-000000000003','c9000000-0000-4000-8000-000000000001'),('a9000000-0000-4000-8000-000000000003','c9000000-0000-4000-8000-000000000002'),('a9000000-0000-4000-8000-000000000004','c9000000-0000-4000-8000-000000000001');
insert into public.customer_memberships(user_id,customer_id) values('a9000000-0000-4000-8000-000000000005','c9000000-0000-4000-8000-000000000001');
create function pg_temp.task(n integer,who integer default 3,delta integer default 0,state text default 'todo',client integer default 1) returns jsonb language sql as $$select public.save_crm_record(('c9000000-0000-4000-8000-'||lpad(client::text,12,'0'))::uuid,'tasks',('d9000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,null,jsonb_build_object('title',case when who=4 then 'HIDDEN OTHER TASK' else 'Działanie '||n end,'description','TASK DESCRIPTION','kind','follow_up','dueOn',to_char((now() at time zone 'Europe/Warsaw')::date+delta,'YYYY-MM-DD'),'assigneeId','a9000000-0000-4000-8000-'||lpad(who::text,12,'0'),'contactId',null,'state',state,'result',''))$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select pg_temp.task(1),pg_temp.task(2,3,-1),pg_temp.task(3,3,1,'in_progress'),pg_temp.task(4,3,0,'done'),pg_temp.task(5,3,-2,'cancelled'),pg_temp.task(6,4),pg_temp.task(7,3,0,'todo',2),pg_temp.task(8,2),pg_temp.task(9,2,-1),pg_temp.task(10,1);
select public.save_crm_record('c9000000-0000-4000-8000-000000000001','notes','da900000-0000-4000-8000-000000000001',null,jsonb_build_object('title','PRIVATE NOTE','body','PRIVATE BODY','kind','note','occurredOn',to_char((now() at time zone 'Europe/Warsaw')::date,'YYYY-MM-DD'),'contactId',null,'archived',false));
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000003',true);
select is((public.my_crm_tasks('today','',1)->>'viewerId')::text,'a9000000-0000-4000-8000-000000000003','Viewer is authenticated caller');
select is(public.my_crm_tasks()->>'today',to_char((now() at time zone 'Europe/Warsaw')::date,'YYYY-MM-DD'),'Agenda day independent of session timezone');
select is((public.my_crm_tasks('today','',1)->>'total')::text,'2','today filter has exact own scoped tasks');
select is((public.my_crm_tasks('today','',1)->'counts'->>'today')::text,'2','today counter ignores selected filter');
select is((public.my_crm_tasks('overdue','',1)->>'total')::text,'1','overdue filter has exact own scoped tasks');
select is((public.my_crm_tasks('today','',1)->'counts'->>'overdue')::text,'1','overdue counter ignores selected filter');
select is((public.my_crm_tasks('upcoming','',1)->>'total')::text,'1','upcoming filter has exact own scoped tasks');
select is((public.my_crm_tasks('today','',1)->'counts'->>'upcoming')::text,'1','upcoming counter ignores selected filter');
select is((public.my_crm_tasks('open','',1)->>'total')::text,'4','open filter has exact own scoped tasks');
select is((public.my_crm_tasks('today','',1)->'counts'->>'open')::text,'4','open counter ignores selected filter');
select is((public.my_crm_tasks('closed','',1)->>'total')::text,'2','closed filter has exact own scoped tasks');
select is((public.my_crm_tasks('today','',1)->'counts'->>'closed')::text,'2','closed counter ignores selected filter');
select is((public.my_crm_tasks('open','kLiEnT bEtA',1)->>'total')::text,'1','Search by customer case insensitive');
select is((public.my_crm_tasks('open','Działanie 2',1)->>'total')::text,'1','Search task title');
select is((public.my_crm_tasks('open','%',1)->>'total')::text,'0','Percent searched literally not as wildcard');
select is((public.my_crm_tasks('open','TASK DESCRIPTION',1)->>'total')::text,'0','Description not used in search');
select ok(public.my_crm_tasks('open')::text !~ 'PRIVATE NOTE|PRIVATE BODY|HIDDEN OTHER TASK|agenda-4','No notes or other assignees in agenda');
select is((public.my_crm_tasks('closed','',1)->'counts'->>'open')::text,'4','Closed filter still returns open summary');
select throws_ok($$select public.my_crm_tasks('all')$$,'22023',null,'Invalid filter search or page rejected');
select throws_ok($$select public.my_crm_tasks('today','',0)$$,'22023',null,'Invalid filter search or page rejected');
select throws_ok($$select public.my_crm_tasks('today','',100001)$$,'22023',null,'Invalid filter search or page rejected');
select throws_ok($$select public.my_crm_tasks('today',repeat('x',161))$$,'22023',null,'Invalid filter search or page rejected');
select throws_ok($$select public.my_crm_tasks('today',E'bad\nquery')$$,'22023',null,'Invalid filter search or page rejected');
select throws_ok($$select public.my_crm_tasks('today',' query ')$$,'22023',null,'Invalid filter search or page rejected');
select throws_ok($$select public.my_crm_tasks(null)$$,'22023',null,'Invalid filter search or page rejected');
select is((public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',0,'done','Contacted')->>'version')::text,'1','Quick progress uses canonical record');
select is((public.my_crm_tasks('today','',1)->>'total')::text,'1','Completed task leaves today list');
select is((public.my_crm_tasks('today','',1)->'counts'->>'closed')::text,'3','Closed counter updates');
select is((public.customer_crm_summary('c9000000-0000-4000-8000-000000000001')->>'openTasks')::text,'2','Customer summary updates with same progress');
select is((public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',0,'done','Contacted')->>'version')::text,'1','Retry does not duplicate progress');
select is((public.crm_task_progress('c9000000-0000-4000-8000-000000000001','d9000000-0000-4000-8000-000000000001',1,'todo','Reopened')->>'version')::text,'2','Reopen via progress');
select is((public.my_crm_tasks('today','',1)->>'total')::text,'2','Reopened task returns to today');
reset role;
delete from public.staff_customer_assignments where user_id='a9000000-0000-4000-8000-000000000003' and customer_id='c9000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000003',true);
select is((public.my_crm_tasks('today','',1)->>'total')::text,'1','Revoked customer removed from list');
select is((public.my_crm_tasks('today','',1)->'counts'->>'open')::text,'3','Revoked customer removed from counts');
select is((public.my_crm_tasks('open','Beta',1)->>'total')::text,'0','Search cannot recover revoked customer');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select is((public.my_crm_tasks('open','',1)->>'total')::text,'2','Office agenda is personal not whole team');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000001',true);
select is((public.my_crm_tasks('open','',1)->>'total')::text,'1','Admin agenda also personal');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000002',true);
select pg_temp.task(n,3,-10,'done') from generate_series(20,42) n;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000003',true);
select is((public.my_crm_tasks('closed','',1)->>'total')::text,'25','Paged result total not truncated');
select is((jsonb_array_length(public.my_crm_tasks('closed','',1)->'items'))::text,'20','First page bounded to twenty');
select is((jsonb_array_length(public.my_crm_tasks('closed','',2)->'items'))::text,'5','Second page contains remainder');
select ok(not exists(select 1 from jsonb_array_elements(public.my_crm_tasks('closed')->'items') a join jsonb_array_elements(public.my_crm_tasks('closed','',2)->'items') b on a->>'id'=b->>'id'),'Stable pages do not overlap');
select is((public.my_crm_tasks('upcoming','',1)->'items'->0->>'customerPage')::text,'2','Customer link targets actual page including closed rows');
select is((public.crm_records('c9000000-0000-4000-8000-000000000001','tasks','all',2)->'items'->-1->>'id')::text,'d9000000-0000-4000-8000-000000000003','Customer target page contains selected task');
select is((jsonb_array_length(public.my_crm_tasks('closed','',100000)->'items'))::text,'0','Out of range valid page returns empty rows');
reset role;
update public.customers set archived_at=now() where id='c9000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000003',true);
select is((public.my_crm_tasks('open','',1)->>'total')::text,'0','Archived customer omitted from active agenda');
select is((public.my_crm_tasks('closed','',1)->>'total')::text,'0','Archived customer history stays in customer profile');
reset role;
insert into public.account_access(user_id,blocked) values('a9000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select throws_ok($$select public.my_crm_tasks('today','',1)$$,'42501',null,'Blocked user denied');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000005',true);
select throws_ok($$select public.my_crm_tasks('today','',1)$$,'42501',null,'Client and no-role user denied');
select set_config('request.jwt.claim.sub','a9000000-0000-4000-8000-000000000006',true);
select throws_ok($$select public.my_crm_tasks('today','',1)$$,'42501',null,'Client and no-role user denied');
reset role;
set local role anon;
select throws_ok($$select public.my_crm_tasks('today','',1)$$,'42501',null,'Anonymous execution denied');
select * from finish();
rollback;
